def divisors_sum(n):
    """Return the sum of the proper divisors of n."""
    divisors = [1]  # Start with 1, which is a divisor of every number
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n // i)
    return sum(divisors)

